'@ | ConvertFrom-Json
function HashText([string]$s) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($s)))).Replace('-','').ToLowerInvariant() } finally { $sha.Dispose() }
}
$pending=@()
foreach($p in $patch) {
    $path=Join-Path $RepoRoot $p.path
    $bytes=[IO.File]::ReadAllBytes($path)
    $bom=$bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191
    $raw=[IO.File]::ReadAllText($path); $nl=if($raw.Contains("`r`n")){"`r`n"}else{"`n"}
    $source=$raw.Replace("`r`n","`n"); $hash=HashText $source
    if($hash -eq $p.after){continue}
    if($hash -ne $p.before){throw "Source mismatch: $($p.path). No files changed. Expected supplied v5.0 snapshot."}
    foreach($c in $p.changes){$source=$source.Remove([int]$c.start,[int]$c.length).Insert([int]$c.start,[string]$c.text)}
    if((HashText $source) -ne $p.after){throw "Patch verification failed: $($p.path). No files changed."}
    $pending+=@{name=$p.path;path=$path;target=$source.Replace("`n",$nl);encoding=[Text.UTF8Encoding]::new($bom)}
}
if(!$pending.Count){Write-Host 'Scanner v5.1 already installed.';return}
$backup=Join-Path $RepoRoot ('.guidevault-patch-backups/magazine-scanner-v51-'+(Get-Date -Format 'yyyyMMdd-HHmmss-fff'))
foreach($p in $pending){$dest=Join-Path $backup $p.name; New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest)|Out-Null; Copy-Item -LiteralPath $p.path -Destination $dest; if((Get-FileHash -LiteralPath $p.path).Hash -ne (Get-FileHash -LiteralPath $dest).Hash){throw 'Backup verification failed.'}}
try {foreach($p in $pending){[IO.File]::WriteAllText($p.path,$p.target,$p.encoding);if([IO.File]::ReadAllText($p.path) -cne $p.target){throw "Verification failed: $($p.name)"};Write-Host "Updated: $($p.name)"}} catch {foreach($p in $pending){Copy-Item -LiteralPath (Join-Path $backup $p.name) -Destination $p.path -Force};throw}
Write-Host "Backup: $backup"
Write-Host 'Scanner v5.1 applied. Build and deploy backend and UI together. Test a single magazine before batch scans.'
